CREATE TABLE IF NOT EXISTS "draft_picks" ("id" integer primary key autoincrement not null, "draft_id" integer not null, "ordinal" integer not null, "pack_number" integer not null, "pick_number" integer not null, "pack_id" integer, "direction" integer, "cards_available" text not null, "picked_catalog_id" integer, "picked_card_id" integer, "reservations" text not null, "shown_at" datetime, "deadline_at" datetime, "picked_at" datetime, "note" text, "created_at" datetime, "updated_at" datetime, foreign key("draft_id") references "drafts"("id") on delete cascade);
CREATE UNIQUE INDEX "draft_picks_draft_id_ordinal_unique" on "draft_picks" ("draft_id", "ordinal");
CREATE INDEX "draft_picks_pack_id_index" on "draft_picks" ("pack_id");
CREATE INDEX "draft_picks_picked_catalog_id_index" on "draft_picks" ("picked_catalog_id");
CREATE TABLE IF NOT EXISTS "limited_deck_snapshots" ("id" integer primary key autoincrement not null, "league_id" integer not null, "match_id" integer, "game_id" integer, "source" varchar not null, "cards" text not null, "signature" text not null, "captured_at" datetime not null, "created_at" datetime, "updated_at" datetime, "match_token" varchar, foreign key("league_id") references "leagues"("id") on delete cascade, foreign key("match_id") references "matches"("id") on delete set null, foreign key("game_id") references "games"("id") on delete set null);
CREATE UNIQUE INDEX "limited_snapshots_league_match_source_unique" on "limited_deck_snapshots" ("league_id", "match_id", "source");
CREATE INDEX "log_events_draft_discovery_idx" on "log_events" ("event_type", "processed_at", "draft_token");
CREATE TABLE IF NOT EXISTS "sync_state" ("id" integer primary key autoincrement not null, "type" varchar not null, "last_synced_at" datetime, "canonical_version" integer not null, "full_cursor" integer, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "sync_state_type_unique" on "sync_state" ("type");
CREATE TABLE IF NOT EXISTS "sync_rejections" ("id" integer primary key autoincrement not null, "type" varchar not null, "client_id" varchar not null, "reason" varchar not null, "hash" varchar not null, "created_at" datetime, "updated_at" datetime);
CREATE UNIQUE INDEX "sync_rejections_type_client_id_unique" on "sync_rejections" ("type", "client_id");
CREATE INDEX "limited_deck_snapshots_match_token_index" on "limited_deck_snapshots" ("match_token");
CREATE TABLE IF NOT EXISTS "sideboard_guides" ("id" integer primary key autoincrement not null, "deck_id" integer not null, "archetype_id" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("deck_id") references "decks"("id") on delete cascade, foreign key("archetype_id") references "archetypes"("id") on delete cascade);
CREATE UNIQUE INDEX "sideboard_guides_deck_id_archetype_id_unique" on "sideboard_guides" ("deck_id", "archetype_id");
CREATE TABLE IF NOT EXISTS "sideboard_guide_cards" ("id" integer primary key autoincrement not null, "sideboard_guide_id" integer not null, "oracle_id" varchar not null, "direction" varchar not null, "quantity" integer not null, "created_at" datetime, "updated_at" datetime, foreign key("sideboard_guide_id") references "sideboard_guides"("id") on delete cascade);
CREATE UNIQUE INDEX "sideboard_guide_cards_unique_entry" on "sideboard_guide_cards" ("sideboard_guide_id", "oracle_id", "direction");
CREATE INDEX "matches_manual_index" on "matches" ("manual");
CREATE UNIQUE INDEX "accounts_login_id_unique" on "accounts" ("login_id");
